class Solution {
  private static final long MOD = 1_000_000_007L;

  public int minimumCost(int[] nums, int k) {
    long prefix = 0, ops = 0;
    for (int v : nums) {
      prefix += v;
      ops = Math.max(ops, (prefix + k - 1) / k - 1);
    }
    long a = ops % MOD, b = (ops + 1) % MOD;
    long inv2 = (MOD + 1) / 2;
    return (int) (a * b % MOD * inv2 % MOD);
  }
}
